    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            RecordListState::Open => "open",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "open" => Some(RecordListState::Open),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        RecordListEvent::Null
    }

    // NL→IR Item C1 Path A: store the current event's typed `_event.data`
    // payload so native transition guards can read it without a script
    // engine. Called by the engine's pop loop for every dequeued event;
    // events injected without a typed payload carry the `#[default] None`
    // variant, against which the variant-specific guards simply fail.
    fn populate_event_payload(&mut self, payload: &Self::Payload) {
        self.pending_payload = payload.clone();
    }

    // NL→IR Item C1 Path A: …and when no typed payload rode with the event,
    // read that view out of the `data` every other producer fills — `<send>`
    // with `<param>`, an invoke forwarding either way, autoforward, BasicHTTP,
    // mesh. A payload that does not read as this event's schema is returned as
    // a refusal, on which the engine refuses the delivery whole and takes an
    // `error.execution` in its place (docs/adr/0086, section 4.2).
    fn lift_event_payload(
        &mut self,
        event: Self::Event,
        data: &str,
    ) -> ::core::result::Result<(), ::sce_rust_runtime::event_payload::PayloadRefusal> {
        // A typed payload already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if self.pending_payload != RecordListPayload::None {
            return Ok(());
        }
        match event {
            RecordListEvent::RecordListAnnounce => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListAnnounce(RecordListRecordListAnnouncePayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                    });
            }
            RecordListEvent::RecordListChange => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListChange(RecordListRecordListChangePayload {
                        by: fields.field("by").and_then(|v| v.unsigned64())?,
                        wallTime: fields.field("wallTime").and_then(|v| v.signed64())?,
                        counter: fields.field("counter").and_then(|v| v.unsigned::<u32>())?,
                        ops: fields.field("ops").and_then(|v| {
                            v.list_within::<_, 64>(1, |v| {
                                v.record(None, |r| {
                                    Ok(RecordListOpRecord {
                                        kind: r.field("kind").and_then(|v| v.unsigned::<u8>())?,
                                        id: r.field("id").and_then(|v| v.unsigned::<u32>())?,
                                        field: r
                                            .field("field")
                                            .and_then(|v| v.unsigned::<u16>())?,
                                        value: r.field("value").and_then(|v| v.signed64())?,
                                        text: r.field("text").and_then(|v| v.text::<96>())?,
                                        wallTime: r.field("wallTime").and_then(|v| v.signed64())?,
                                        counter: r
                                            .field("counter")
                                            .and_then(|v| v.unsigned::<u32>())?,
                                        nodeId: r.field("nodeId").and_then(|v| v.unsigned64())?,
                                    })
                                })
                            })
                        })?,
                    });
            }
            RecordListEvent::RecordListClear => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"command\":\"0\"}",
                    )?;
                self.pending_payload =
                    RecordListPayload::RecordListClear(RecordListRecordListClearPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            RecordListEvent::RecordListConfirm => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListConfirm(RecordListRecordListConfirmPayload {
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            RecordListEvent::RecordListEdit => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"more\":false,\"command\":\"0\"}",
                    )?;
                self.pending_payload =
                    RecordListPayload::RecordListEdit(RecordListRecordListEditPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        value: fields.signed64("value")?,
                        text: fields.text("text", 32)?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            RecordListEvent::RecordListJoin => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"journal\":true}",
                    )?;
                self.pending_payload =
                    RecordListPayload::RecordListJoin(RecordListRecordListJoinPayload {
                        node: fields.unsigned64("node")?,
                        journal: fields.truth("journal")?,
                    });
            }
            RecordListEvent::RecordListRaise => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListRaise(RecordListRecordListRaisePayload {
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            RecordListEvent::RecordListRecall => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListRecall(RecordListRecordListRecallPayload {
                        by: fields.field("by").and_then(|v| v.unsigned64())?,
                        wallTime: fields.field("wallTime").and_then(|v| v.signed64())?,
                        counter: fields.field("counter").and_then(|v| v.unsigned::<u32>())?,
                        ops: fields.field("ops").and_then(|v| {
                            v.list_within::<_, 64>(1, |v| {
                                v.record(None, |r| {
                                    Ok(RecordListOpRecord {
                                        kind: r.field("kind").and_then(|v| v.unsigned::<u8>())?,
                                        id: r.field("id").and_then(|v| v.unsigned::<u32>())?,
                                        field: r
                                            .field("field")
                                            .and_then(|v| v.unsigned::<u16>())?,
                                        value: r.field("value").and_then(|v| v.signed64())?,
                                        text: r.field("text").and_then(|v| v.text::<96>())?,
                                        wallTime: r.field("wallTime").and_then(|v| v.signed64())?,
                                        counter: r
                                            .field("counter")
                                            .and_then(|v| v.unsigned::<u32>())?,
                                        nodeId: r.field("nodeId").and_then(|v| v.unsigned64())?,
                                    })
                                })
                            })
                        })?,
                        command: fields.field("command").and_then(|v| v.unsigned64())?,
                        provisional: fields.field("provisional").and_then(|v| v.truth())?,
                    });
            }
            RecordListEvent::RecordListRestore => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListRestore(RecordListRecordListRestorePayload {
                        by: fields.field("by").and_then(|v| v.unsigned64())?,
                        wallTime: fields.field("wallTime").and_then(|v| v.signed64())?,
                        counter: fields.field("counter").and_then(|v| v.unsigned::<u32>())?,
                        ops: fields.field("ops").and_then(|v| {
                            v.list_within::<_, 64>(1, |v| {
                                v.record(None, |r| {
                                    Ok(RecordListOpRecord {
                                        kind: r.field("kind").and_then(|v| v.unsigned::<u8>())?,
                                        id: r.field("id").and_then(|v| v.unsigned::<u32>())?,
                                        field: r
                                            .field("field")
                                            .and_then(|v| v.unsigned::<u16>())?,
                                        value: r.field("value").and_then(|v| v.signed64())?,
                                        text: r.field("text").and_then(|v| v.text::<96>())?,
                                        wallTime: r.field("wallTime").and_then(|v| v.signed64())?,
                                        counter: r
                                            .field("counter")
                                            .and_then(|v| v.unsigned::<u32>())?,
                                        nodeId: r.field("nodeId").and_then(|v| v.unsigned64())?,
                                    })
                                })
                            })
                        })?,
                    });
            }
            RecordListEvent::RecordListRetire => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"command\":\"0\"}",
                    )?;
                self.pending_payload =
                    RecordListPayload::RecordListRetire(RecordListRecordListRetirePayload {
                        id: fields.unsigned::<u32>("id")?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            RecordListEvent::RecordListRole => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListRole(RecordListRecordListRolePayload {
                        node: fields.unsigned64("node")?,
                        role: fields.unsigned::<u8>("role")?,
                    });
            }
            RecordListEvent::RecordListRoom => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListRoom(RecordListRecordListRoomPayload {
                        values: fields.unsigned::<u32>("values")?,
                        history: fields.unsigned::<u32>("history")?,
                        digest: fields.unsigned::<u32>("digest")?,
                    });
            }
            RecordListEvent::RecordListVerdict => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListVerdict(RecordListRecordListVerdictPayload {
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        outcome: match fields.field("outcome")?.name()? {
                            "none" => RecordListOutcomeEnum::None,
                            "accepted" => RecordListOutcomeEnum::Accepted,
                            "held" => RecordListOutcomeEnum::Held,
                            "waiting" => RecordListOutcomeEnum::Waiting,
                            "refused" => RecordListOutcomeEnum::Refused,
                            other => {
                                return Err(fields.unknown_variant("outcome", other, "Outcome"))
                            }
                        },
                        reason: fields.optional("reason", |fields| {
                            Ok(match fields.field("reason")?.name()? {
                                "notWriter" => RecordListRefusalEnum::NotWriter,
                                "noRoomForValue" => RecordListRefusalEnum::NoRoomForValue,
                                "noRoomForHistory" => RecordListRefusalEnum::NoRoomForHistory,
                                "noRoomForDigest" => RecordListRefusalEnum::NoRoomForDigest,
                                "changeTooLarge" => RecordListRefusalEnum::ChangeTooLarge,
                                "registerNamedTwice" => RecordListRefusalEnum::RegisterNamedTwice,
                                "clockExhausted" => RecordListRefusalEnum::ClockExhausted,
                                "peerRefused" => RecordListRefusalEnum::PeerRefused,
                                other => {
                                    return Err(fields.unknown_variant("reason", other, "Refusal"))
                                }
                            })
                        })?,
                    });
            }
            RecordListEvent::RecordListWithdraw => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    RecordListPayload::RecordListWithdraw(RecordListRecordListWithdrawPayload {
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        command: fields.unsigned64("command")?,
                    });
            }
            _ => {}
        }
        Ok(())
    }

    // W3C SCXML 5.10: Populate pending event metadata from EventWithMetadata
    // Ports C++ EventMetadataHelper::populatePolicyFromMetadata
    fn populate_event_metadata(&mut self, metadata: &sce_rust_runtime::EventMetadata) {
        self.pending_event_invokeid = metadata.invoke_id.clone();
    }

    // W3C SCXML 5.10: Clear pending event metadata after transition processing
    // Ports C++ EventMetadataHelper::clearPolicyMetadata
    fn clear_event_metadata(&mut self) {
        self.pending_event_invokeid.clear();
    }

